package com.mendes.scheduling_platform.blockedperiod; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.*; import java.util.*;
public interface BlockedPeriodRepository extends JpaRepository<BlockedPeriod,Long> { List<BlockedPeriod> findAllByTenantIdAndVenueId(Long tenantId,Long venueId); Optional<BlockedPeriod> findByIdAndTenantId(Long id,Long tenantId); @Query("select count(b)>0 from BlockedPeriod b where b.tenantId=:t and b.venueId=:v and :start < b.endDateTime and :end > b.startDateTime") boolean overlaps(@Param("t") Long tenantId,@Param("v") Long venueId,@Param("start") OffsetDateTime start,@Param("end") OffsetDateTime end); }
